/*
 * Transcoding tests for the srvsvc coders: every request and reply
 * structure, and every arm of the CONNECT_ENUM_UNION, FILE_ENUM_UNION,
 * FILE_INFO, SESSION_ENUM_UNION, SHARE_ENUM_UNION, SHARE_INFO and
 * SERVER_INFO unions. See coder-test.h for the tests run per case.
 *
 * Where the known-good NDR stubs come from (win16-1, Windows Server 2016):
 *
 * - Replies were captured from the server. Windows always replies in its
 *   native format, so there are only NDR32 and NDR64 little-endian ones.
 * - Requests were encoded by libdcerpc and sent to the server, which
 *   accepted them as NDR32 LE, NDR32 BE and NDR64 LE: it answered with the
 *   same status for each flavor rather than faulting with
 *   RPC_X_BAD_STUB_DATA. Windows does not support NDR64 BE.
 * - Requests that would change the server were sent so that they fail
 *   after the stub is unmarshalled: NetrShareSetInfo, NetrShareDel and
 *   NetrShareDelSticky on a share that does not exist, NetrShareAdd with
 *   a path that does not exist, NetrSessionDel and NetrFileClose on a
 *   session and file that do not exist. Levels a call does not support
 *   return ERROR_INVALID_LEVEL or ERROR_INVALID_PARAMETER, also after
 *   unmarshalling. NetrServerSetInfo was sent with the server's current
 *   values.
 * - NetrShareGetInfo does not support levels 1004, 1006 and 1501; those
 *   SHARE_INFO arms are covered by the NetrShareSetInfo requests.
 *
 * The data was generated from the captures; replies whose NDR32 and NDR64
 * captures differ in live values are split into one case per capture.
 */

#include <stdint.h>
#include <stddef.h>

#include <dcerpc/dcerpc.h>
#include <dcerpc/srvsvc.h>

#include "coder-test.h"

